package com.bananalab.lite;
import android.content.*;import org.json.*;import java.util.*;import java.util.regex.*;
/** Question planning and grounded retrieval. Never sends the conversation or project to a search engine. */
final class ResearchConversation{
 static String cleanQuery(String q){return q.replaceAll("[\\p{Cntrl}]"," ").replaceAll("\\s+"," ").trim().substring(0,Math.min(240,q.replaceAll("[\\p{Cntrl}]"," ").replaceAll("\\s+"," ").trim().length()));}
 static String strip(String text){return text.trim().replaceFirst("(?iu)^(?:por favor[, ]+)?(?:busc[aá](?:me)?(?: en internet| en la web)?|investig[aá](?: en internet)?|averigu[aá]|explic[aá]me|cont[aá]me sobre|quiero (?:saber|entender)(?: sobre)?|qu[eé] sab[eé]s (?:sobre|de)|aprend[eé] sobre)\\s+","").replaceFirst("(?iu)\\s+(?:en internet|por favor)[?.!]*$","").trim();}
 static boolean question(String raw){String q=ChatLanguage.normalize(raw);if(q.matches("(?s).*(mi proyecto|mi escena|mis personajes|el borrador|que podes hacer|que sabes hacer|como hago para que hablen|como (?:puedo |hago para )?(?:dibujar|animar|crear|guardar|exportar)|como cambio|que voz|quien (?:tiene|recibio)|quien soy|como me llamo).*"))return false;return q.matches("(?s)^(?:busca(?:me)? |investiga |averigua |que (?:es|son|significa|sabes|paso|pasa|diferencia|ventajas|desventajas)|quien (?:es|fue)|quienes son|por que |porque |como (?:funciona|se |puedo |son |es |hacer |aprender |mejorar |instalar |usar |cocinar |conseguir )|cuando |donde |cuanto |cuanta |cuantos |cuantas |cual |cuales |explicame |podes explicarme |me explicas |quiero (?:saber|entender) |compara |diferencias entre |beneficios de |ventajas de ).*")||raw.trim().endsWith("?")&&q.length()>12;}
 static boolean followup(String q){return q.matches("(?s)(?:y )?(?:eso|sobre eso|contame mas|decime mas|amplia eso|amplia|explicalo mejor|no entendi|mas detalles|y por que|por que|como funciona|dame un ejemplo|actualiza eso|busca de nuevo|resumi eso|resumilo|segui con eso)")||q.matches("(?s)^(?:y (?:como|donde|cuando|que|cuanto|por que)|y (?:sus|las|los) (?:ventajas|desventajas)).*");}
 static boolean privateQuestion(String raw){String q=ChatLanguage.normalize(raw);return q.matches("(?s).*(?:mi contrasena|mi clave|mi domicilio|mi direccion|mi dni|mi tarjeta|mi telefono|mi correo|mi nombre|mi cuenta|mi pareja|mi esposa|me siento|estoy triste).*")||q.matches("(?s)^(?:como me llamo|que sabes de mi|que recordas de mi|mi nombre|mi contrasena|mi clave|mi dni|mi domicilio).*");}
 static String reply(Context c,String message,String previous)throws Exception{return reply(c,message,previous,ResearchWeb.NETWORK,true);}
 static String reply(Context c,String message,String previous,ResearchWeb.Transport transport,boolean schedule)throws Exception{
  String q=ChatLanguage.normalize(message),query="";SharedPreferences p=ResearchStore.prefs(c);
  if(ChatLanguage.socialReply(message)!=null||q.matches("como me llamo|cual es mi nombre|te acordas de mi nombre|que me gusta|te acordas que me gusta|quien sos|que sos|como te llamas"))return null;
  if(q.equals("biblioteca web"))return ResearchStore.library(c);
  if(q.matches("mi aprendizaje|estado del aprendizaje|temas que seguis|biblioteca web|que aprendiste|estado de internet"))return ResearchStore.status(c);
  if(q.matches("pausa el aprendizaje|pausa aprendizaje|desactiva aprendizaje|no aprendas en segundo plano|detene el aprendizaje")){if(!p.edit().putBoolean("enabled",false).commit())throw new java.io.IOException("No pude pausar la actualización.");if(schedule)ResearchScheduler.configure(c);return "Pausé las actualizaciones de fondo. Podés seguir buscando desde la conversación.";}
  if(q.matches("activa aprendizaje|activa el aprendizaje|continua aprendiendo|aprende en segundo plano")){if(!p.edit().putBoolean("enabled",true).commit())throw new java.io.IOException("No pude activar la actualización.");if(schedule)ResearchScheduler.configure(c);return "Activé la actualización de temas guardados. "+ResearchStore.status(c);}
  if(q.matches("borra biblioteca web|borra lo aprendido de internet")){ResearchStore.clear(c);return "Borré las fuentes web, los temas seguidos y el contexto de búsqueda. Tu proyecto y tus recuerdos personales se conservan.";}
  Matcher stop=Pattern.compile("(?:deja de aprender sobre|deja de seguir) (.+)").matcher(q);if(stop.matches())return ResearchStore.unfollow(c,stop.group(1))?"Dejé de seguir ese tema.":"Ese tema no estaba en seguimiento.";
  boolean learn=q.startsWith("aprende sobre ")||q.startsWith("segui aprendiendo sobre ")||q.startsWith("mantene actualizado ");if(learn){String prefix=q.startsWith("segui")?"segui aprendiendo sobre ":q.startsWith("mantene")?"mantene actualizado ":"aprende sobre ";query=cleanQuery(message.trim().substring(prefix.length()));ResearchStore.follow(c,query);if(schedule)ResearchScheduler.configure(c);}
  boolean offline=q.startsWith("busca en tu biblioteca ")||q.startsWith("que guardaste sobre ");if(offline)query=message.trim().substring(q.startsWith("busca")?"busca en tu biblioteca ".length():"que guardaste sobre ".length()).trim();
  boolean follow=followup(q);String last=p.getString("lastQuery",previous==null?"":previous);if(follow){if(last.isEmpty())return "¿Sobre qué tema querés que siga? Decime el nombre o la pregunta completa.";query=last;if(!q.matches("(?s)(?:y )?(?:eso|sobre eso|contame mas|decime mas|amplia eso|amplia|explicalo mejor|no entendi|mas detalles|actualiza eso|busca de nuevo|resumi eso|resumilo|segui con eso)"))query=cleanQuery(last+" "+message);}
  boolean direct=q.startsWith("lee https://")||q.startsWith("consulta https://");if(!learn&&!offline&&!follow&&!direct&&!question(message))return null;
  if(privateQuestion(message))return "No voy a enviar tus datos personales al buscador. Podemos trabajar con tus recuerdos locales; para investigar, escribí una pregunta general sin esos datos.";
  if(query.isEmpty())query=cleanQuery(strip(message));if(query.length()<3)return "Decime qué tema o pregunta querés investigar.";
  if(!offline&&!direct&&!learn&&!follow&&p.getBoolean("followQueries",true)){try{ResearchStore.follow(c,query);}catch(java.io.IOException full){/* Existing topics stay intact; explicit follow reports the limit. */}}
  if(offline){List<ResearchWeb.Doc> docs=ResearchStore.search(c,query);return docs.isEmpty()?"No tengo fuentes guardadas pertinentes sobre ese tema.":ResearchAnswer.render(query,docs,true,"");}
  boolean refresh=q.startsWith("actualiza")||q.equals("busca de nuevo")||query.matches("(?iu).*(?:hoy|actual|ahora|ultimo|último|noticias|precio|presidente|cotizacion|cotización).*"),summarize=q.equals("resumi eso")||q.equals("resumilo");
  List<ResearchWeb.Doc> cached=ResearchStore.search(c,query);boolean fresh=!cached.isEmpty()&&ResearchAnswer.score(query,cached.get(0).title+" "+cached.get(0).text)>=Math.max(1,Math.sqrt(ResearchAnswer.terms(query).size())*.65)&&System.currentTimeMillis()-cached.get(0).saved<ResearchStore.DAY;
  if(!learn&&!direct&&!refresh&&!q.matches("(?s)^(?:compara |diferencias? entre |que diferencia hay entre ).*")&&(fresh||summarize)&&!cached.isEmpty()){int depth=follow&&!summarize?Math.min(10,p.getInt("depth",0)+1):0;remember(c,query,cached);p.edit().putInt("depth",depth).apply();return ResearchAnswer.render(query,cached,true,"",depth);}
  ResearchWeb.Batch result;String comparison="";Matcher compare=Pattern.compile("(?iu)^(?:compara|diferencias? entre|qu[eé] diferencia hay entre) (.+?) (?:con|y|versus|vs\\.?) (.+?)[?.!]*$").matcher(message.trim());
  if(direct){String address=message.trim().substring(message.indexOf(' ')+1).trim();result=ResearchWeb.read(address,transport);query=result.docs.isEmpty()?address:result.docs.get(0).title;}
  else if(compare.matches()){String a=cleanQuery(compare.group(1)),b=cleanQuery(compare.group(2));ResearchWeb.Batch first=ResearchWeb.search(a,transport),second=ResearchWeb.search(b,transport);result=new ResearchWeb.Batch();if(!first.docs.isEmpty())result.docs.add(first.docs.get(0));if(!second.docs.isEmpty())result.docs.add(second.docs.get(0));result.warning=first.warning+(second.warning.equals(first.warning)?"":" "+second.warning);comparison="Comparación solicitada: "+a+" / "+b+". Reuní evidencia por separado; no doy un ganador sin datos comparables.\n\n";}
  else result=ResearchWeb.search(query,transport);
  if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("Consulta cancelada.");
  if(result.docs.isEmpty()){if(learn)ResearchStore.checked(c,query,"No se encontraron fuentes legibles");if(!cached.isEmpty())return (learn?"Tema agregado al seguimiento.\n\n":"")+ResearchAnswer.render(query,cached,true,"La consulta nueva falló o no devolvió evidencia; conservo la copia anterior.");return (learn?"Tema agregado al seguimiento.\n":"")+"No pude obtener fuentes pertinentes. Puede faltar conexión, el proveedor estar bloqueado o no haber páginas legibles. No modifiqué la escena ni inventé una respuesta. "+result.warning;}
  ResearchStore.documents(c,result.docs);remember(c,query,result.docs);if(learn)ResearchStore.checked(c,query,"Fuentes consultadas");return (learn?"Agregué el tema para actualizarlo en segundo plano.\n\n":"")+comparison+ResearchAnswer.render(query,result.docs,false,result.warning);
 }
 static void remember(Context c,String query,List<ResearchWeb.Doc> docs)throws Exception{JSONArray ids=new JSONArray();for(ResearchWeb.Doc d:docs)ids.put(d.url);if(!ResearchStore.prefs(c).edit().putString("lastQuery",query).putString("lastDocs",ids.toString()).putInt("depth",0).commit())throw new java.io.IOException("No pude guardar el contexto de la pregunta.");}
 static void updateOne(Context c,ResearchWeb.Transport transport)throws Exception{if(!ResearchStore.prefs(c).getBoolean("enabled",true))return;long generation=ResearchStore.prefs(c).getLong("generation",0);String query=ResearchStore.due(c);if(query.isEmpty())return;ResearchWeb.Batch result=ResearchWeb.search(query,transport);if(Thread.currentThread().isInterrupted())throw new java.io.InterruptedIOException("Actualización cancelada.");synchronized(ResearchStore.class){if(!ResearchStore.prefs(c).getBoolean("enabled",true)||generation!=ResearchStore.prefs(c).getLong("generation",0)||!ResearchStore.following(c,query))return;if(!result.docs.isEmpty())ResearchStore.documents(c,result.docs);ResearchStore.checked(c,query,result.docs.isEmpty()?"Sin fuentes nuevas; conservé las anteriores":"Actualizado · "+result.docs.size()+" fuentes"+(result.warning.isEmpty()?"":" · cobertura limitada"));}}
}
